			// strided add over a whole output row.
			for ic := 0; ic < c.InC; ic++ {
				src := x.Plane(n, ic)
				wbase := ((oc * c.InC) + ic) * c.KH * c.KW
				for kh := 0; kh < c.KH; kh++ {
					for kw := 0; kw < c.KW; kw++ {
						wv := c.Weight[wbase+kh*c.KW+kw]
						if wv == 0 {
							continue
						}
						for oh := 0; oh < outH; oh++ {
							ih := oh + kh - c.Pad
							if ih < 0 || ih >= x.H {
								continue
							}
