							// input column is in bounds, so the inner loop
							// carries no branch.
							lo, hi := 0, outW
							if v := c.Pad - kw; v > lo {
								lo = v
							}
							if v := x.W + c.Pad - kw; v < hi {
								hi = v
							}
							if lo >= hi {
								continue
							}
							drow := dst[oh*outW : (oh+1)*outW]
							srow := src[ih*x.W : (ih+1)*x.W]
							base := kw - c.Pad
							for ow := lo; ow < hi; ow++ {
								drow[ow] += wv * srow[ow+base]
							}
						}
					}
				}
