// The default is segments, which is what OpenAI's verbose_json returns when
// nothing is named.
func (r *TranscriptionRequest) Wants(kind string) bool {
	all := append(append(StringList{}, r.Granularities...), r.GranularitiesArray...)
	if len(all) == 0 {
		return kind == "segment"
	}
	for _, g := range all {
		if g == kind {
			return true
		}
	}
	return false
}

