cat > zimage/vae/gpu_encoder_test.go <<'EOF'
package vae

import (
	"os"
	"testing"

	"strix-halo-vulkan/vk"
)

// gpuEncTol is the bound the matrix-core encoder is held to.
//
// It is the fp16 convolution's bound (gpu_conv_test.go's 3e-2 for the same
// kernel) and not the fp32 graph's 5e-3, because every one of the encoder's 27
// convolutions narrows its operands here. The *composition* is what says that
// is enough: the latent this produces is fed to a denoising loop whose own
// end-to-end bound against diffusers is 3e-2 (stage 6), and IMAGE.md I7's
// edit test measures the whole path rather than trusting this number.
const gpuEncTol = 3e-2

func loadEncoder(t *testing.T) *Encoder {
	t.Helper()
	if _, err := os.Stat(vaeDir); err != nil {
		t.Skipf("no VAE checkpoint at %s", vaeDir)
	}
	enc, err := LoadEncoder(vaeDir, FluxConfig())
	if err != nil {
		t.Fatal(err)
	}
	return enc
}

func newTestEncoder(t *testing.T, dev *vk.Device, cpu *Encoder, h, w int, opt Options) *GPUEncoder {
	t.Helper()
	g, err := NewGPUEncoderOpts(dev, cpu, h, w, opt)
	if err != nil {
		t.Fatal(err)
	}
	return g
}

// TestGPUEncoderAgainstDiffusers runs the Vulkan graph on the same image the
// CPU port was validated on, and holds it to both oracles: the diffusers dump
// and the CPU port itself.
//
// Both, because they answer different questions. Against diffusers is "the
// encoder is right"; against the CPU port -- which shares this graph's
// architecture but none of its arithmetic -- is "the shaders are right", and
// a graph assembled out of the wrong dispatches fails that one by a lot.
func TestGPUEncoderAgainstDiffusers(t *testing.T) {
	cpu := loadEncoder(t)
	m := loadEncManifest(t)
	dev, done := newTestDevice(t)
	defer done()

	img := loadRef(t, m, "image_in")
	g := newTestEncoder(t, dev, cpu, img.H, img.W, Options{})
	defer g.Destroy()
	n, err := g.Dispatches(img.H, img.W)
	if err != nil {
		t.Fatal(err)
	}
	attn, gemm, conv := g.Kernels()
	t.Logf("kernels attn=%s gemm=%s conv=%s, %d dispatches, %d MB fp32 + %d MB fp16 arena",
		attn, gemm, conv, n, g.ActivationBytes()>>20, g.F16ActivationBytes()>>20)

	got, err := g.Apply(img)
	if err != nil {
		t.Fatal(err)
	}
	compareTol(t, "moments (gpu vs diffusers)", got, loadRef(t, m, "moments"), gpuEncTol)

	want, err := cpu.Apply(img)
	if err != nil {
		t.Fatal(err)
	}
	compareTol(t, "moments (gpu vs cpu)", got, want, gpuEncTol)

	// Encode is the call the pipeline makes, and it reads back half as many
	// channels as Apply. Getting that slice wrong reads the log-variance,
	// which is the control in encoder_test.go's TestEncoderValidationDetects-
	// Errors -- so the two calls are checked to agree rather than assumed to.
	mode, err := g.Encode(img)
	if err != nil {
		t.Fatal(err)
	}
	compareTol(t, "mode (gpu vs diffusers)", mode, loadRef(t, m, "mode"), gpuEncTol)
}

// TestGPUEncoderScalarPath holds the fp32 graph -- no matrix cores anywhere --
// to the tight bound the CPU port meets, which is what says the *graph* is
// right independently of what the narrowing costs.
//
// It is a separate test rather than a sub-case because it is the slow path
// PIPELINE.md's second rule says to keep: the fast one is measured against it,
// and without it a shared bug in the pack and the kernel would pass.
func TestGPUEncoderScalarPath(t *testing.T) {
	cpu := loadEncoder(t)
	m := loadEncManifest(t)
	dev, done := newTestDevice(t)
	defer done()

	img := loadRef(t, m, "image_in")
	g := newTestEncoder(t, dev, cpu, img.H, img.W, Options{Attn: AttnScalar, Conv: ConvScalar})
	defer g.Destroy()

	got, err := g.Apply(img)
	if err != nil {
		t.Fatal(err)
	}
	// The same bound the CPU port is held to at the same tensor: this graph
	// is fp32 throughout, so the only difference from diffusers is summation
	// order.
	compareTol(t, "moments (fp32 gpu vs diffusers)", got, loadRef(t, m, "moments"), encOutTol)
}

// TestGPUEncoderOneEncoderManySizes is the residency claim as a test: the
// arenas are built once for the largest image and every smaller one runs in
// them. A server sizes its encoder for its ceiling and a request may be any
// size under it, so this is the property /v1/images/edits rests on.
//
// The negative control is in here: an image larger than the arenas is refused
// rather than allowed to overrun. The graph is re-recorded per encode, so
// nothing else would catch it until the latent came back wrong.
func TestGPUEncoderOneEncoderManySizes(t *testing.T) {
	cpu := loadEncoder(t)
	dev, done := newTestDevice(t)
	defer done()

	const maxH, maxW = 256, 256
	g := newTestEncoder(t, dev, cpu, maxH, maxW, Options{})
	defer g.Destroy()

	for _, sz := range [][2]int{{256, 256}, {128, 256}, {256, 128}, {64, 64}} {
		h, w := sz[0], sz[1]
		img := NewTensor(1, 3, h, w)
		for i := range img.Data {
			img.Data[i] = float32((i%211)-105) / 105
		}
		got, err := g.Encode(img)
		if err != nil {
			t.Fatalf("%dx%d: %v", h, w, err)
		}
		if got.C != cpu.LatentChannels || got.H != h/8 || got.W != w/8 {
			t.Errorf("%dx%d encoded to %s, want [1 %d %d %d]", h, w, got, cpu.LatentChannels, h/8, w/8)
		}
	}

	big := NewTensor(1, 3, maxH*2, maxW)
	if _, err := g.Encode(big); err == nil {
		t.Error("an image past the arenas was accepted; it would overrun them silently")
	} else {
		t.Logf("refused, as it must be: %v", err)
	}

	// And a side that is not a multiple of 8, which the subsampling identity
	// needs at each of the three halvings.
	odd := NewTensor(1, 3, 60, 64)
	if _, err := g.Encode(odd); err == nil {
		t.Error("a 60-pixel side was accepted; three halvings do not divide it")
	}
}
