			c.name, le, le/stepTol, ie, ie/imageTol)
	}
}

func maxAbs(got, want []float32) float64 {
	var m float64
	for i := range want {
		if d := math.Abs(float64(got[i]) - float64(want[i])); d > m {
			m = d
		}
	}
	return m
}

func fmtErrs(v []float64) string {
	s := ""
	for _, e := range v {
		s += fmt.Sprintf("%.2g ", e)
	}
	return s
}
