	raw, err := decodeImageField(req.Image[0])
	if err != nil {
		badRequest(w, "image: "+err.Error())
		return
	}
	init, kind, err := image.Decode(bytes.NewReader(raw))
	if err != nil {
		badRequest(w, "image: this server decodes png and jpeg: "+err.Error())
		return
